import{z as i,x as A,o as r,c as d,q as o,j as n,D as e,d as l,s as E,S as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"二分查找","description":"","frontmatter":{"title":"二分查找","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/binary-search.md","filePath":"cs/binary-search.md","lastUpdated":1791413859000}'),p={name:"cs/binary-search.md"};function h(B,a,c,m,T,_){const t=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=o('<h1 id="二分查找" tabindex="-1">二分查找 <a class="header-anchor" href="#二分查找" aria-label="Permalink to &quot;二分查找&quot;">​</a></h1><div class="epigraph"><p>有序数组上每次丢掉一半；比较次数 $\\Theta(\\log n)$，合并是常数，分治退化成单侧。</p><footer>—— 据 Knuth, TAOCP vol. 3；CLRS 第 2 章整理</footer></div><p>上一课<a href="/cs/divide-conquer">分治</a>钉了分解–递归–合并，并用<a href="/cs/master-theorem">主定理</a>读 \\(T(n)=aT(n/b)+f(n)\\)。本课不重写三步定义。缺口是一份最瘦的实例：有序数组里找键，切成两半后<strong>只走一侧</strong>，合并是 \\(\\Theta(1)\\)。后课插入与归并才对照「循环扩前缀」和「两半都递归」。本课只把二分钉成有序上的分治。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无序数组找键只能线性扫。若已按<a href="/cs/sort-lower-bound">比较</a>排好，中点一次比较就能丢掉一半：目标小于中点则右半不可能，反之左半不可能。递归式 \\(T(n)=T(\\lfloor n/2\\rfloor)+\\Theta(1)\\)，主定理情形二的退化，\\(\\Theta(\\log n)\\)。缺口不是再证明有序，而是承认：<strong>分治不必两半都解</strong>；信息在比较里，另一半被谓词杀掉。</p><p><span class="marginnote">数字实例：一百万个数，线性查找最多比 100 万次；二分只要 \\(\\lfloor\\log_2 10^6\\rfloor+1=20\\) 次——每次比较把候选砍半，\\(2^{20}\\) 就超过一百万，20 刀砍完。</span></p><p>循环写法维护区间 \\([L,R)\\)，不变式「若存在则在区间内」。递归与循环同一逻辑；本课两者都认，不把栈当必需。</p><h3 id="有序是前提-不是本课的产物" tabindex="-1">有序是前提，不是本课的产物 <a class="header-anchor" href="#有序是前提-不是本课的产物" aria-label="Permalink to &quot;有序是前提，不是本课的产物&quot;">​</a></h3><p>二分不排序。把无序数组先排再找，代价被排序主导，不是本课的 \\(\\log n\\)。相等键：返回任一、最左或最右，是边界约定，要在不变式里写清，不能靠「看起来中间那个」。</p><p><span class="marginnote">Knuth 把二分当作有序表上的标准检索。CLRS 用它练循环不变式与递归式。后课排序算法才生产有序；本课消费有序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>取中点 \\(m\\)。比较 \\(A[m]\\) 与目标：相等结束；小于则 \\(L\\leftarrow m+1\\)；大于则 \\(R\\leftarrow m\\)。空区间则失败。正确性：每次区间真缩小，且答案若在原区间则仍在。代价：\\(\\lfloor\\log_2 n\\rfloor+O(1)\\) 次比较。</p>',12)),(r(),n(s,null,{default:e(()=>[E(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORD%5B%22%E6%9C%89%E5%BA%8F%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20MID%5B%22%E6%AF%94%E8%BE%83%E4%B8%AD%E7%82%B9%22%5D%0A%20%20MID%20--%3E%20L%5B%22%E5%8F%AA%E8%B5%B0%E5%B7%A6%E5%8D%8A%22%5D%0A%20%20MID%20--%3E%20R%5B%22%E5%8F%AA%E8%B5%B0%E5%8F%B3%E5%8D%8A%22%5D%0A%20%20MID%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p>不要对无序数组「二分」：中点没有丢掉一半的权利。也不要把树的检索（<a href="/cs/bst">BST</a>）与数组下标中点混成同一实现；前者走指针，后者是随机访问。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/array-random-access">数组随机访问</a>让中点 \\(\\Theta(1)\\)。链表上中点要走 \\(\\Theta(n)\\)，二分失去意义。整数溢出：\\((L+R)/2\\) 在定长整数上可能爆；用 \\(L+(R-L)/2\\)。这是编码细节，不改变渐近。</p><p><span class="marginnote">常见误区：写 <code>mid = (L+R)/2</code> 看似自然，但当 \\(L\\)、\\(R\\) 都接近 20 亿时，相加先溢出成负数、区间瞬间乱掉；<code>L + (R-L)/2</code> 先做差就安全。这是真实事故级的编码细节，不是洁癖。</span></p><p>下界：比较模型里检索有序表也要 \\(\\Omega(\\log n)\\) 次，决策树高度。本课点名，完整排序下界仍后置。</p><p>为什么至少要 \\(\\log n\\) 次比较（决策树视角）：</p>',6)),(r(),n(s,null,{default:e(()=>[E(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%A0%B9%EF%BC%9A%E6%AF%94%E8%BE%83%20A%5Bm%5D%20%E4%B8%8E%E7%9B%AE%E6%A0%87%5D%20--%3E%20L1%5B%E7%9B%AE%E6%A0%87%E5%81%8F%E5%B0%8F%EF%BC%9A%E5%80%99%E9%80%89%E7%A0%8D%E5%88%B0%20n%2F2%22%5D%0A%20%20R%20--%3E%20R1%5B%22%E7%9B%AE%E6%A0%87%E5%81%8F%E5%A4%A7%EF%BC%9A%E5%80%99%E9%80%89%E7%A0%8D%E5%88%B0%20n%2F2%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E5%86%8D%E6%AF%94%E8%BE%83%EF%BC%9A%E5%86%8D%E7%A0%8D%E5%8D%8A%22%5D%0A%20%20R1%20--%3E%20R2%5B%22%E5%86%8D%E6%AF%94%E8%BE%83%EF%BC%9A%E5%86%8D%E7%A0%8D%E5%8D%8A%22%5D%0A%20%20L2%20--%3E%20BOT%5B%22%E5%8F%B6%EF%BC%9A%E5%94%AF%E4%B8%80%E7%A1%AE%E5%AE%9A%E7%AD%94%E6%A1%88%22%5D%0A%20%20R2%20--%3E%20BOT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p><span class="marginnote">直觉类比：把所有可能的比较序列画成一棵树，每次比较是一个分叉、候选减半；\\(k\\) 次比较至多区分 \\(2^k\\) 种结果。要在一百万个位置里指出一个，树高至少 20 层——这就是 \\(\\Omega(\\log n)\\) 的来源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不排。不处理插值检索、指数检索、旋转数组上的变体。也不把二分答案（对单调谓词搜阈值）写成数值算法附录。后课默认：有序数组检索 \\(\\Theta(\\log n)\\) 比较。插入与归并对照循环与两路分治。</p><p>后课默认：谈到有序表上的找，先二分。全表排序从下一课开始。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有序数组上分治只走一侧，\\(T(n)=T(n/2)+\\Theta(1)=\\Theta(\\log n)\\)。</li><li>不变式管区间；无序或链表使方法失效。</li><li>本课不生产有序，只消费有序。</li><li>出处：Knuth, TAOCP vol. 3；CLRS 第 2 章。</li></ul>',6))])}const u=i(p,[["render",h]]);export{f as __pageData,u as default};
